// DoorLock: switch-based hierarchical state machine generated by MachinaState.
// Do not edit by hand. Derive from this class and implement the guard and action hooks.
#pragma once

#include <cstddef>

namespace Security {

    class DoorLock {
      public:
        enum class State {
            Locked,
            Unlocked,
            Alarm,
            None
        };

        enum class Event {
            EnterCode,
            Lock,
            Timeout,
            Reset
        };

        enum class TraceKind {
            Start,        // name = machine name
            Event,        // name = event being dispatched
            Ignored,      // name = event no state handled
            Transition,   // name = "Source -> Target"
            Exit,         // name = state being exited
            Enter         // name = state being entered
        };

        static constexpr std::size_t kStateCount  = 3;
        static constexpr std::size_t kEventCount  = 4;
        static constexpr std::size_t kRegionCount = 1;   // region 0 is the top level
        static constexpr std::size_t kQueueCapacity = 16;

        virtual ~DoorLock() = default;

        // Resets the machine (running timers are cancelled, history is forgotten) and enters the initial state configuration.
        void Start() {
            const ScopedLock lock(*this);
            for (State& state : active_) {
                state = State::None;
            }
            queueHead_  = 0;
            queueCount_ = 0;
            Trace(TraceKind::Start, "DoorLock");
            EnterDown(State::None, State::Locked);
            DrainQueue();
        }

        // Dispatches an event to the innermost active states first. Returns false if the event was not handled.
        bool Dispatch(Event event) {
            const ScopedLock lock(*this);
            switch (event) {
                case Event::EnterCode:
                case Event::Reset:
                    return false;   // use the typed Dispatch method / internal event
                default:
                    break;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(event);
            args_ = nullptr;
            DrainQueue();
            return handled;
        }

        bool DispatchEnterCode(int code) {
            const ScopedLock lock(*this);
            const EnterCodeArgs args { code };
            args_ = &args;
            const bool handled = DispatchCore(Event::EnterCode);
            args_ = nullptr;
            DrainQueue();
            return handled;
        }

        bool DispatchReset(int code) {
            const ScopedLock lock(*this);
            const ResetArgs args { code };
            args_ = &args;
            const bool handled = DispatchCore(Event::Reset);
            args_ = nullptr;
            DrainQueue();
            return handled;
        }

        // Innermost active state (following the first region of orthogonal states).
        State Current() const {
            const ScopedLock lock(*this);
            return Innermost(active_[0]);
        }

        // True if the given state is active.
        bool IsIn(State state) const {
            const ScopedLock lock(*this);
            return state != State::None && active_[RegionOf(state)] == state;
        }

        // True once a top-level final state has been reached.
        bool IsFinished() const {
            const ScopedLock lock(*this);
            return false;
        }

        static State ParentOf(State state) {
            (void)state;
            return State::None;
        }

        static const char* StateName(State state) {
            switch (state) {
                case State::Locked:
                    return "Locked";
                case State::Unlocked:
                    return "Unlocked";
                case State::Alarm:
                    return "Alarm";
                default:
                    return "None";
            }
        }

        static const char* EventName(Event event) {
            switch (event) {
                case Event::EnterCode:
                    return "EnterCode";
                case Event::Lock:
                    return "Lock";
                case Event::Timeout:
                    return "Timeout";
                case Event::Reset:
                    return "Reset";
                default:
                    return "";
            }
        }

      protected:
        // Mutual exclusion around every public member, e.g. backed by a mutable std::mutex.
        // Hooks must not call public members of this class unless the lock is recursive.
        virtual void Lock() const   = 0;
        virtual void Unlock() const = 0;
        // Override to log state machine activity.
        virtual void Trace(TraceKind kind, const char* name) {
            (void)kind;
            (void)name;
        }
        // Queues an event from inside a hook; it is processed after the current event. Returns false if the queue is full.
        bool Post(Event event) {
            switch (event) {
                case Event::EnterCode:
                case Event::Reset:
                    return false;
                default:
                    break;
            }
            QueuedEvent entry {};
            entry.event = event;
            return Enqueue(entry);
        }
        bool PostEnterCode(int code) {
            QueuedEvent entry {};
            entry.event = Event::EnterCode;
            entry.EnterCode_code = code;
            return Enqueue(entry);
        }
        bool PostReset(int code) {
            QueuedEvent entry {};
            entry.event = Event::Reset;
            entry.Reset_code = code;
            return Enqueue(entry);
        }
        // Guards
        virtual bool isValidCode(int code) = 0;
        virtual bool tooManyAttempts(int code) = 0;
        virtual bool isAdminCode(int code) = 0;
        // Actions
        virtual void engageBolt() = 0;
        virtual void releaseBolt() = 0;
        virtual void sirenOn() = 0;
        virtual void sirenOff() = 0;
        virtual void resetAttempts(int code) = 0;
        virtual void countFailure(int code) = 0;

      private:
        class ScopedLock {
          public:
            explicit ScopedLock(const DoorLock& owner) : owner_(owner) {
                owner_.Lock();
            }
            ~ScopedLock() {
                owner_.Unlock();
            }
            ScopedLock(const ScopedLock&)            = delete;
            ScopedLock& operator=(const ScopedLock&) = delete;

          private:
            const DoorLock& owner_;
        };

        // Arguments of the event being dispatched; only valid during Dispatch.
        struct EnterCodeArgs {
            int code;
        };
        const EnterCodeArgs& ArgsOfEnterCode() const {
            return *static_cast<const EnterCodeArgs*>(args_);
        }

        struct ResetArgs {
            int code;
        };
        const ResetArgs& ArgsOfReset() const {
            return *static_cast<const ResetArgs*>(args_);
        }

        const void* args_ = nullptr;

        struct QueuedEvent {
            Event event;
            int EnterCode_code;
            int Reset_code;
        };

        bool Enqueue(const QueuedEvent& entry) {
            if (queueCount_ == kQueueCapacity) {
                return false;
            }
            queue_[(queueHead_ + queueCount_) % kQueueCapacity] = entry;
            ++queueCount_;
            return true;
        }

        void DrainQueue() {
            while (queueCount_ > 0) {
                const QueuedEvent entry = queue_[queueHead_];
                queueHead_              = (queueHead_ + 1) % kQueueCapacity;
                --queueCount_;
                switch (entry.event) {
                    case Event::EnterCode: {
                        const EnterCodeArgs args { entry.EnterCode_code };
                        args_ = &args;
                        DispatchCore(entry.event);
                        args_ = nullptr;
                        break;
                    }
                    case Event::Reset: {
                        const ResetArgs args { entry.Reset_code };
                        args_ = &args;
                        DispatchCore(entry.event);
                        args_ = nullptr;
                        break;
                    }
                    default:
                        DispatchCore(entry.event);
                        break;
                }
            }
        }

        bool DispatchCore(Event event) {
            Trace(TraceKind::Event, EventName(event));
            if (active_[0] != State::None && DispatchState(active_[0], event)) {
                return true;
            }
            Trace(TraceKind::Ignored, EventName(event));
            return false;
        }

        // Offers the event to every active region below `state` first, then to `state` itself.
        bool DispatchState(State state, Event event) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (active_[region] != State::None && DispatchState(active_[region], event)) {
                    return true;
                }
            }
            return HandleEvent(state, event);
        }

        bool HandleEvent(State state, Event event) {
            switch (state) {
                case State::Locked:
                    switch (event) {
                        case Event::EnterCode:
                            if (isValidCode(ArgsOfEnterCode().code)) {
                                Trace(TraceKind::Transition, "Locked -> Unlocked");
                                ExitState(State::Locked);
                                resetAttempts(ArgsOfEnterCode().code);
                                EnterDown(State::None, State::Unlocked);
                                return true;
                            }
                            if (tooManyAttempts(ArgsOfEnterCode().code)) {
                                Trace(TraceKind::Transition, "Locked -> Alarm");
                                ExitState(State::Locked);
                                EnterDown(State::None, State::Alarm);
                                return true;
                            }
                            Trace(TraceKind::Transition, "Locked (internal)");
                            countFailure(ArgsOfEnterCode().code);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Unlocked:
                    switch (event) {
                        case Event::Lock:
                            Trace(TraceKind::Transition, "Unlocked -> Locked");
                            ExitState(State::Unlocked);
                            EnterDown(State::None, State::Locked);
                            return true;
                        case Event::Timeout:
                            Trace(TraceKind::Transition, "Unlocked -> Locked");
                            ExitState(State::Unlocked);
                            EnterDown(State::None, State::Locked);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Alarm:
                    switch (event) {
                        case Event::Reset:
                            if (isAdminCode(ArgsOfReset().code)) {
                                Trace(TraceKind::Transition, "Alarm -> Locked");
                                ExitState(State::Alarm);
                                resetAttempts(ArgsOfReset().code);
                                EnterDown(State::None, State::Locked);
                                return true;
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
            return false;
        }

        static std::size_t RegionOf(State state) {
            (void)state;
            return 0;
        }

        static std::size_t FirstRegionOf(State state) {
            (void)state;
            return 0;
        }

        static std::size_t RegionsOf(State state) {
            (void)state;
            return 0;
        }

        void EnterRegion(std::size_t region) {
            (void)region;
        }

        void OnEntry(State state) {
            switch (state) {
                case State::Locked:
                    engageBolt();
                    break;
                case State::Unlocked:
                    releaseBolt();
                    break;
                case State::Alarm:
                    sirenOn();
                    break;
                default:
                    break;
            }
        }

        void OnExit(State state) {
            switch (state) {
                case State::Alarm:
                    sirenOff();
                    break;
                default:
                    break;
            }
        }

        void ExitState(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first + RegionsOf(state); region-- > first;) {
                if (active_[region] != State::None) {
                    ExitState(active_[region]);
                }
            }
            Trace(TraceKind::Exit, StateName(state));
            OnExit(state);
            active_[RegionOf(state)] = State::None;
        }

        // Enters every state from below `from` down to `target`, then follows default (initial) transitions
        // below `target`.
        void EnterDown(State from, State target) {
            State state = target;
            State next  = State::None;
            while (ParentOf(state) != from) {
                next  = state;
                state = ParentOf(state);
            }
            EnterState(state);
            if (next == State::None) {
                EnterDefault(state);
                return;
            }
            EnterDown(state, target);
        }

        void EnterState(State state) {
            active_[RegionOf(state)] = state;
            Trace(TraceKind::Enter, StateName(state));
            OnEntry(state);
        }

        void EnterDefault(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                EnterRegion(region);
            }
        }

        State Innermost(State state) const {
            while (state != State::None && RegionsOf(state) > 0 && active_[FirstRegionOf(state)] != State::None) {
                state = active_[FirstRegionOf(state)];
            }
            return state;
        }

        State active_[kRegionCount] = { State::None };   // active state per region
        QueuedEvent queue_[kQueueCapacity] = {};
        std::size_t queueHead_  = 0;
        std::size_t queueCount_ = 0;
    };
}
